import{_ as e,C as t,c as i,o as n,j as o,b as a,a0 as r,a as l,w as s,G as d,a1 as u}from"./chunks/framework.DKRgXLPU.js";const h=JSON.parse('{"title":"Je voorbereiding op de fotosessie opbouwen","description":"","frontmatter":{},"headers":[],"relativePath":"nl/education/mental-strength/pre-shot-routine.md","filePath":"nl/education/mental-strength/pre-shot-routine.md"}');const p=e({name:"nl/education/mental-strength/pre-shot-routine.md"},[["render",function(e,h,p,g,c,b){const k=t("Mermaid");return n(),i("div",null,[h[1]||(h[1]=o("h1",{id:"je-voorbereiding-op-de-fotosessie-opbouwen",tabindex:"-1"},[l("Je voorbereiding op de fotosessie opbouwen "),o("a",{class:"header-anchor",href:"#je-voorbereiding-op-de-fotosessie-opbouwen","aria-label":'Permalink to "Je voorbereiding op de fotosessie opbouwen"'},"​")],-1)),h[2]||(h[2]=o("p",null,"Je voorbereiding op een worp is een van de krachtigste mentale hulpmiddelen. Het is een consistente reeks handelingen die je voorbereidt op elke worp en je optimale prestatietoestand activeert.",-1)),h[3]||(h[3]=o("div",{class:"tip custom-block"},[o("p",{class:"custom-block-title"},"Het Grote Idee"),o("p",null,[o("strong",null,"Je routine is je toegangspoort tot de zone."),l(' Een consistente routine vóór een schot geeft je hersenen het signaal: "Het is tijd om te presteren." Door herhaling wordt het een automatische trigger voor topprestaties.')])],-1)),(n(),a(u,null,{default:s(()=>[d(k,{id:"mermaid-11",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BStartroutine%5D%20--%3E%20B%5BDe%20hersenen%20herkennen%20een%20patroon.%5D%0A%20%20%20%20B%20--%3E%20C%5BAutomatische%20toestandsverschuiving%5D%0A%20%20%20%20C%20--%3E%20D%5BUitvoeringsmodus%5D%0A%20%20%20%20D%20--%3E%20E%5BMaximale%20prestaties%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23e8f5e9%0A%20%20%20%20style%20D%20fill%3A%23fff4e1%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A"})]),fallback:s(()=>[...h[0]||(h[0]=[l(" Loading... ",-1)])]),_:1})),h[4]||(h[4]=r('<h2 id="waarom-routines-werken" tabindex="-1">Waarom routines werken <a class="header-anchor" href="#waarom-routines-werken" aria-label="Permalink to &quot;Waarom routines werken&quot;">​</a></h2><h3 id="consistentie-schept-zelfvertrouwen" tabindex="-1">Consistentie schept zelfvertrouwen. <a class="header-anchor" href="#consistentie-schept-zelfvertrouwen" aria-label="Permalink to &quot;Consistentie schept zelfvertrouwen.&quot;">​</a></h3><p>Als je steeds hetzelfde doet, elimineer je variabelen. Je lichaam weet wat er gaat komen. Dit creëert een gevoel van controle en vertrouwdheid, zelfs in onbekende situaties.</p><h3 id="routines-activeren-toestanden" tabindex="-1">Routines activeren toestanden <a class="header-anchor" href="#routines-activeren-toestanden" aria-label="Permalink to &quot;Routines activeren toestanden&quot;">​</a></h3><p>Door herhaling raakt je routine gekoppeld aan je prestatievermogen. Het starten van de routine zet automatisch de mentale omschakeling naar de uitvoeringsmodus in gang.</p><h3 id="routines-blokkeren-afleidingen" tabindex="-1">Routines blokkeren afleidingen. <a class="header-anchor" href="#routines-blokkeren-afleidingen" aria-label="Permalink to &quot;Routines blokkeren afleidingen.&quot;">​</a></h3><p>Een routine geeft je geest iets om zich op te concentreren. Er is geen ruimte voor zorgen over de score, het publiek of wat er zou kunnen gebeuren.</p><h3 id="routines-helpen-bij-het-beheersen-van-opwinding" tabindex="-1">Routines helpen bij het beheersen van opwinding. <a class="header-anchor" href="#routines-helpen-bij-het-beheersen-van-opwinding" aria-label="Permalink to &quot;Routines helpen bij het beheersen van opwinding.&quot;">​</a></h3><p>Een goed opgezette routine helpt je energieniveau te reguleren: het kalmeert je als je te energiek bent en helpt je je te concentreren als je je futloos voelt.</p><h2 id="elementen-van-een-effectieve-routine" tabindex="-1">Elementen van een effectieve routine <a class="header-anchor" href="#elementen-van-een-effectieve-routine" aria-label="Permalink to &quot;Elementen van een effectieve routine&quot;">​</a></h2><h3 id="fase-1-beoordeling-buiten-de-cirkel" tabindex="-1">Fase 1: Beoordeling (buiten de cirkel) <a class="header-anchor" href="#fase-1-beoordeling-buiten-de-cirkel" aria-label="Permalink to &quot;Fase 1: Beoordeling (buiten de cirkel)&quot;">​</a></h3><p>Voordat je naar binnen gaat, verzamel eerst de volgende informatie:</p><ul><li>Lees het terrein (hellingen, obstakels, ondergrond).</li><li>Beoordeel de situatie (score, posities van de boules)</li><li>Kies je doelwit en landingsplek.</li><li>Bepaal het type worp (wijzen, schieten, lobben, rollen)</li></ul><p><strong>Dit is de plek waar nagedacht wordt.</strong> Neem hier de tijd.</p><h3 id="fase-2-overgang-de-cirkel-betreden" tabindex="-1">Fase 2: Overgang (De cirkel betreden) <a class="header-anchor" href="#fase-2-overgang-de-cirkel-betreden" aria-label="Permalink to &quot;Fase 2: Overgang (De cirkel betreden)&quot;">​</a></h3><p>De omschakeling van denken naar doen:</p><ul><li>Fysieke actie (stap op een consistente manier in de cirkel)</li><li>Mentale aanwijzing (een woord of zin die &quot;uitvoeringsmodus&quot; aangeeft)</li><li>Ademhaling (één bewuste ademhaling om jezelf te centreren)</li></ul><p><strong>Dit is de schakelaar.</strong> De analyse stopt hier.</p><h3 id="fase-3-opzetten-in-de-cirkel" tabindex="-1">Fase 3: Opzetten (in de cirkel) <a class="header-anchor" href="#fase-3-opzetten-in-de-cirkel" aria-label="Permalink to &quot;Fase 3: Opzetten (in de cirkel)&quot;">​</a></h3><p>Bereid je lichaam voor:</p><ul><li>Een consistente houding (altijd dezelfde)</li><li>Gripcontrole (voel de boule)</li><li>Afstemming op het doel</li><li>Fysieke trigger (een kleine beweging die je zelf maakt)</li></ul><h3 id="fase-4-visualisatie-kort" tabindex="-1">Fase 4: Visualisatie (Kort) <a class="header-anchor" href="#fase-4-visualisatie-kort" aria-label="Permalink to &quot;Fase 4: Visualisatie (Kort)&quot;">​</a></h3><p>Bekijk de worp voordat je hem maakt:</p><ul><li>Stel je de baan van de bal voor (maximaal 2-3 seconden).</li><li>Voel de succesvolle worp</li><li>Maak visueel contact met je doelgroep.</li></ul><h3 id="fase-5-uitvoering" tabindex="-1">Fase 5: Uitvoering <a class="header-anchor" href="#fase-5-uitvoering" aria-label="Permalink to &quot;Fase 5: Uitvoering&quot;">​</a></h3><p>Gooi de bal:</p><ul><li>Externe focus (alleen doel)</li><li>Vertrouw op je lichaam.</li><li>Zonder aarzeling vrijgeven</li><li>Ga er natuurlijk mee door</li></ul><h2 id="het-opbouwen-van-je-persoonlijke-routine" tabindex="-1">Het opbouwen van je persoonlijke routine <a class="header-anchor" href="#het-opbouwen-van-je-persoonlijke-routine" aria-label="Permalink to &quot;Het opbouwen van je persoonlijke routine&quot;">​</a></h2><h3 id="stap-1-observeer-wat-je-al-doet" tabindex="-1">Stap 1: Observeer wat je al doet <a class="header-anchor" href="#stap-1-observeer-wat-je-al-doet" aria-label="Permalink to &quot;Stap 1: Observeer wat je al doet&quot;">​</a></h3><p>Je hebt waarschijnlijk al een bepaalde routine. Let op:</p><ul><li>Wat doe je voordat je een goede worp maakt?</li><li>Wat voelt voor jou natuurlijk aan?</li><li>Wat helpt jou om je te concentreren?</li></ul><h3 id="stap-2-ontwerp-je-routine" tabindex="-1">Stap 2: Ontwerp je routine <a class="header-anchor" href="#stap-2-ontwerp-je-routine" aria-label="Permalink to &quot;Stap 2: Ontwerp je routine&quot;">​</a></h3><p>Maak een reeks die het volgende bevat:</p><ul><li>[ ] Beoordelingsfase</li><li>[ ] Duidelijk overgangsmoment</li><li>[ ] Consistente fysieke opstelling</li><li>[ ] Korte visualisatie</li><li>[ ] Uitvoeringstrigger</li></ul><h3 id="stap-3-schrijf-het-op" tabindex="-1">Stap 3: Schrijf het op <a class="header-anchor" href="#stap-3-schrijf-het-op" aria-label="Permalink to &quot;Stap 3: Schrijf het op&quot;">​</a></h3><p>Wees specifiek. Bijvoorbeeld:</p><ol><li><strong>Beoordeling:</strong> Terrein analyseren, landingsplek kiezen</li><li><strong>Overgang:</strong> Stap met je linkervoet eerst in de cirkel en zeg &quot;vertrouwen&quot;.</li><li><strong>Voorbereiding:</strong> Voeten op schouderbreedte, grip controleren, schouders uitlijnen</li><li><strong>Visualiseer:</strong> Zie het pad, voel de bevrijding</li><li><strong>Uitvoering:</strong> Ogen op het doel, gooien</li></ol><h3 id="stap-4-oefen-consequent" tabindex="-1">Stap 4: Oefen consequent. <a class="header-anchor" href="#stap-4-oefen-consequent" aria-label="Permalink to &quot;Stap 4: Oefen consequent.&quot;">​</a></h3><p>Pas je routine toe op ELKE worp tijdens de training:</p><ul><li>Gemakkelijke worpen</li><li>Moeilijke worpen</li><li>Als je moe bent</li><li>Als je fris bent</li></ul><p>De routine moet automatisch worden.</p><h3 id="stap-5-verfijn-in-de-loop-van-de-tijd" tabindex="-1">Stap 5: Verfijn in de loop van de tijd <a class="header-anchor" href="#stap-5-verfijn-in-de-loop-van-de-tijd" aria-label="Permalink to &quot;Stap 5: Verfijn in de loop van de tijd&quot;">​</a></h3><p>Je routine zal zich ontwikkelen. Let op wat werkt en pas het aan. Maar verander je routine niet tijdens de wedstrijd, alleen tussen de onderdelen.</p><h2 id="routine-timing" tabindex="-1">Routine timing <a class="header-anchor" href="#routine-timing" aria-label="Permalink to &quot;Routine timing&quot;">​</a></h2><p>Je routine moet een vaste hoeveelheid tijd in beslag nemen:</p><ul><li>Te snel: Je hebt haast en bent niet goed voorbereid.</li><li>Te traag: Je denkt te veel na en verliest je flow.</li><li>Precies goed: genoeg tijd om je voor te bereiden, maar niet zoveel dat je te veel nadenkt.</li></ul><p><strong>Gebruikelijke timing:</strong></p><ul><li>Beoordeling: 5-10 seconden</li><li>Overgang + Instellen: 3-5 seconden</li><li>Visualisatie + uitvoering: 3-5 seconden</li><li><strong>Totaal: 10-20 seconden</strong></li></ul><h2 id="veelvoorkomende-routinefouten" tabindex="-1">Veelvoorkomende routinefouten <a class="header-anchor" href="#veelvoorkomende-routinefouten" aria-label="Permalink to &quot;Veelvoorkomende routinefouten&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fout</th><th>Probleem</th><th>Oplossing</th></tr></thead><tbody><tr><td>Touwtjespringen tijdens de training</td><td>Routine is niet automatisch.</td><td>Gebruik het bij elke worp.</td></tr><tr><td>Te ingewikkeld</td><td>Moeilijk te onthouden onder druk</td><td>Vereenvoudig tot de essentie.</td></tr><tr><td>Nadenken tijdens de uitvoering</td><td>Verstoort de automatische werking</td><td>Duidelijk overgangspunt</td></tr><tr><td>Inconsistente timing</td><td>Schept onzekerheid</td><td>Oefen met een constant tempo.</td></tr><tr><td>Verandering midden in de wedstrijd</td><td>Wekt twijfel op.</td><td>Blijf bij wat je kent.</td></tr></tbody></table><h2 id="routinematige-probleemoplossing" tabindex="-1">Routinematige probleemoplossing <a class="header-anchor" href="#routinematige-probleemoplossing" aria-label="Permalink to &quot;Routinematige probleemoplossing&quot;">​</a></h2><p><strong>Als je haast hebt:</strong></p><ul><li>Voeg een ademhaling toe tijdens de overgang.</li><li>Vertraag je voorbereidingsbewegingen.</li><li>Neem even een pauze voordat je je visualiseert.</li></ul><p><strong>Als je te veel nadenkt:</strong></p><ul><li>Verkort de routine</li><li>Gebruik een sterker overgangssignaal.</li><li>Richt je meer op de buitenwereld.</li></ul><p><strong>Als je inconsistent bent:</strong></p><ul><li>Maak een video van jezelf om het te controleren.</li><li>Oefen de oefening zonder te gooien.</li><li>Vraag feedback aan een partner.</li></ul><h2 id="voorbeelden-van-routines" tabindex="-1">Voorbeelden van routines <a class="header-anchor" href="#voorbeelden-van-routines" aria-label="Permalink to &quot;Voorbeelden van routines&quot;">​</a></h2><h3 id="eenvoudige-routine" tabindex="-1">Eenvoudige routine <a class="header-anchor" href="#eenvoudige-routine" aria-label="Permalink to &quot;Eenvoudige routine&quot;">​</a></h3><ol><li>Kies een doel</li><li>Stap naar binnen, adem in.</li><li>Grijpen, uitlijnen</li><li>Zie je het, gooi het weg.</li></ol><h3 id="gedetailleerde-routine" tabindex="-1">Gedetailleerde routine <a class="header-anchor" href="#gedetailleerde-routine" aria-label="Permalink to &quot;Gedetailleerde routine&quot;">​</a></h3><ol><li>Bestudeer het terrein, kies een landingsplek.</li><li>Stap eerst met je linkervoet naar binnen.</li><li>Zeg &quot;soepel&quot; inwendig.</li><li>Adem in, schouders zakken</li><li>Voeten neerzetten, grip controleren</li><li>Richt je schouders op het doel.</li><li>Bekijk het pad (2 seconden)</li><li>De blik is gericht op het doelwit.</li><li>Gooien</li></ol><h2 id="belangrijkste-conclusie" tabindex="-1">Belangrijkste conclusie <a class="header-anchor" href="#belangrijkste-conclusie" aria-label="Permalink to &quot;Belangrijkste conclusie&quot;">​</a></h2><blockquote><p>Je routine is je anker. In de chaos is het je constante factor.</p></blockquote><p>Bouw het zorgvuldig op. Oefen het voortdurend. Vertrouw er volledig op.</p>',65))])}]]);export{h as __pageData,p as default};
